<?php $__env->startSection('title', 'Duplicate Videos - Admin VidoHub'); ?>
<?php $__env->startSection('content'); ?>
<style>.duplicate-page{max-width:1100px;margin:auto}.duplicate-head,.duplicate-toolbar,.group-actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.duplicate-head{margin-bottom:22px}.duplicate-head h1{margin:0;font-size:30px}.duplicate-head p,.duplicate-group>p,.duplicate-details small,.selection-note{color:var(--muted)}.duplicate-stats{display:flex;gap:12px;margin-bottom:20px}.duplicate-stat{padding:14px 18px;background:#fff;border:1px solid var(--line);border-radius:12px}.duplicate-stat strong{display:block;font-size:24px}.duplicate-stat span{color:var(--muted);font-size:12px}.duplicate-toolbar{position:sticky;top:76px;z-index:5;flex-wrap:wrap;padding:12px 15px;margin-bottom:18px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 7px 20px #18223810}.duplicate-toolbar button:disabled{opacity:.45;cursor:not-allowed}.duplicate-group{padding:18px;background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:18px}.duplicate-group h2{margin:0;font-size:17px}.duplicate-group>p{margin:3px 0 14px;font-size:13px}.duplicate-row{display:grid;grid-template-columns:24px 150px minmax(0,1fr);gap:14px;align-items:center;padding:12px;border:1px solid var(--line);border-radius:9px;margin-top:8px}.duplicate-row.recommended{border:2px solid #4caf50;background:#f5fff6}.duplicate-row.to-delete{border-color:#ffdede}.duplicate-row input{width:17px;height:17px}.duplicate-thumb{width:150px;aspect-ratio:16/9;object-fit:cover;border-radius:7px;background:linear-gradient(135deg,#252b43,#515b83)}.duplicate-details strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.duplicate-details small{display:block;margin-top:3px}.badge{display:inline-block;margin-bottom:5px;padding:3px 7px;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.05em}.badge.keep{background:#e7f8e9;color:#23833a}.badge.delete{background:#fff0f0;color:#b43737}.group-actions{justify-content:flex-start;margin-top:14px;flex-wrap:wrap}.duplicate-empty{padding:45px;text-align:center;background:#fff;border:1px solid var(--line);border-radius:14px;color:var(--muted)}@media(max-width:650px){.duplicate-head{display:block}.duplicate-stats{flex-wrap:wrap}.duplicate-row{grid-template-columns:22px 100px minmax(0,1fr);gap:8px}.duplicate-thumb{width:100px}.duplicate-toolbar{top:64px;align-items:flex-start;flex-direction:column}}
</style>
<div class="duplicate-page"><div class="duplicate-head"><div><h1>DUPLICATE VIDEOS</h1><p>Kelola duplicate dengan rekomendasi atau pilihan manual.</p></div><a class="btn ghost" href="<?php echo e(route('admin.videos.index')); ?>">Kembali ke Admin</a></div>
<div class="duplicate-stats"><div class="duplicate-stat"><strong><?php echo e($duplicates->count()); ?></strong><span>Duplicate Groups</span></div><div class="duplicate-stat"><strong><?php echo e($duplicates->sum('count')); ?></strong><span>Duplicate Videos</span></div></div>
<?php if(session('success')): ?><div class="panel" style="color:#147a4a"><?php echo e(session('success')); ?></div><?php endif; ?>
<?php if($duplicates->isEmpty()): ?><div class="duplicate-empty">Tidak ditemukan video dengan judul duplicate.</div><?php else: ?><form id="manualDeleteForm" method="POST" action="<?php echo e(route('admin.videos.duplicates.delete')); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><div id="manualInputs"></div></form><form id="recommendedDeleteForm" method="POST" action="<?php echo e(route('admin.videos.duplicates.recommended-all')); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><div id="recommendedInputs"></div></form><div class="duplicate-toolbar"><div><label><input type="checkbox" id="selectAllDuplicates"> SELECT ALL</label><strong id="selectedCount">SELECTED: 0 VIDEOS</strong><p class="selection-note" style="margin:3px 0 0">Select Recommended hanya memilih video KEEP dan tidak menghapusnya.</p></div><div class="group-actions"><button class="btn ghost" type="button" id="selectRecommended">SELECT RECOMMENDED</button><button class="btn ghost" type="button" id="clearSelection">CLEAR SELECTION</button><button class="btn danger" id="deleteSelected" type="button" disabled>DELETE SELECTED</button><button class="btn primary" id="deleteAccording" type="button">DELETE ACCORDING TO RECOMMENDATION</button></div></div><?php $__currentLoopData = $duplicates; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $group): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><section class="duplicate-group" data-group="<?php echo e($group['normalized']); ?>"><h2><?php echo e($group['title']); ?></h2><p><?php echo e($group['count']); ?> duplicate videos · Recommended: KEEP ID <?php echo e($group['keep']); ?></p><?php $__currentLoopData = $group['videos']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $video): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label class="duplicate-row <?php echo e($video->id === $group['keep'] ? 'recommended' : 'to-delete'); ?>" data-id="<?php echo e($video->id); ?>" data-keep="<?php echo e($video->id === $group['keep'] ? '1' : '0'); ?>"><input type="checkbox" value="<?php echo e($video->id); ?>" class="duplicate-checkbox"><span><?php if($video->thumbnail_url): ?><img class="duplicate-thumb" loading="lazy" src="<?php echo e($video->thumbnail_url); ?>" alt=""><?php elseif(\Illuminate\Support\Facades\Storage::disk('public')->exists('thumbnails/'.$video->id.'.jpg')): ?><img class="duplicate-thumb" loading="lazy" src="<?php echo e(route('videos.thumbnail',$video)); ?>" alt=""><?php else: ?><div class="duplicate-thumb"></div><?php endif; ?></span><span class="duplicate-details"><?php if($video->id === $group['keep']): ?><span class="badge keep">RECOMMENDED TO KEEP</span><?php else: ?><span class="badge delete">DUPLICATE</span><?php endif; ?><strong><?php echo e($video->title); ?></strong><small>ID: <?php echo e($video->id); ?> · <?php echo e($video->categories->pluck('name')->join(', ') ?: 'Tanpa kategori'); ?> · <?php echo e($video->models->pluck('name')->join(', ') ?: 'Tanpa model'); ?> · <?php echo e($video->duration ?: '--:--'); ?></small><small><?php echo e($video->file_available ? 'File tersedia' : 'File tidak ditemukan'); ?> · <?php echo e($video->created_at?->format('d M Y H:i')); ?></small></span></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><div class="group-actions"><span class="selection-note">Reason: <?php echo e($group['reason']); ?></span><button class="btn ghost keep-this" type="button" data-group="<?php echo e($group['normalized']); ?>">KEEP THIS (recommended)</button><button class="btn danger delete-group" type="button" data-group="<?php echo e($group['normalized']); ?>" data-title="<?php echo e($group['title']); ?>">DELETE DUPLICATES</button></div></section><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></div>
<script>const selectedVideoIds=new Set();const checkboxes=[...document.querySelectorAll('.duplicate-checkbox')];const all=document.getElementById('selectAllDuplicates');const count=document.getElementById('selectedCount');const deleteSelected=document.getElementById('deleteSelected');const updateSelection=()=>{checkboxes.forEach(box=>box.checked=selectedVideoIds.has(Number(box.value)));const n=selectedVideoIds.size;count.textContent=`SELECTED: ${n} VIDEO${n===1?'':'S'}`;deleteSelected.disabled=n===0;all.checked=checkboxes.length>0&&n===checkboxes.length;all.indeterminate=n>0&&n<checkboxes.length};checkboxes.forEach(box=>box.addEventListener('change',()=>{const id=Number(box.value);box.checked?selectedVideoIds.add(id):selectedVideoIds.delete(id);updateSelection()}));all.addEventListener('change',()=>{checkboxes.forEach(box=>all.checked?selectedVideoIds.add(Number(box.value)):selectedVideoIds.delete(Number(box.value)));updateSelection()});document.getElementById('clearSelection').onclick=()=>{selectedVideoIds.clear();updateSelection()};document.getElementById('selectRecommended').onclick=()=>{document.querySelectorAll('.duplicate-row[data-keep="1"] input').forEach(box=>selectedVideoIds.add(Number(box.value)));updateSelection()};const submitManual=()=>{const form=document.getElementById('manualDeleteForm'),holder=document.getElementById('manualInputs');holder.innerHTML='';selectedVideoIds.forEach(id=>{const input=document.createElement('input');input.type='hidden';input.name='video_ids[]';input.value=id;holder.append(input)});if(!selectedVideoIds.size||!confirm(`DELETE ${selectedVideoIds.size} VIDEOS?\n\nTindakan ini tidak dapat dibatalkan.`))return;form.submit()};deleteSelected.onclick=submitManual;document.querySelectorAll('.keep-this').forEach(button=>button.onclick=()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);group.querySelectorAll('.duplicate-row').forEach(row=>{row.classList.toggle('recommended',row.querySelector('input').value===group.querySelector('.duplicate-row[data-keep="1"] input').value);row.classList.toggle('to-delete',row.querySelector('input').value!==group.querySelector('.duplicate-row[data-keep="1"] input').value)});});document.querySelectorAll('.delete-group').forEach(button=>button.onclick=()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);const keep=group.querySelector('.duplicate-row[data-keep="1"] input').value;const deletes=[...group.querySelectorAll('.duplicate-row:not([data-keep="1"]) input')].map(input=>input.value);const form=document.getElementById('recommendedDeleteForm'),holder=document.getElementById('recommendedInputs');holder.innerHTML=`<input type="hidden" name="keep_id" value="${keep}">${deletes.map(id=>`<input type="hidden" name="delete_ids[]" value="${id}">`).join('')}`;if(confirm(`DELETE DUPLICATES?\n\nKEEP ID ${keep}\nDELETE ${deletes.length} duplicate(s)?`))form.action='<?php echo e(route('admin.videos.duplicates.recommended')); ?>',form.submit()});document.getElementById('deleteAccording').onclick=()=>{const keeps=[...document.querySelectorAll('.duplicate-row[data-keep="1"] input')].map(x=>x.value);const deletes=[...document.querySelectorAll('.duplicate-row:not([data-keep="1"]) input')].map(x=>x.value);const form=document.getElementById('recommendedDeleteForm'),holder=document.getElementById('recommendedInputs');holder.innerHTML=keeps.map(id=>`<input type="hidden" name="keep_ids[]" value="${id}">`).join('')+deletes.map(id=>`<input type="hidden" name="delete_ids[]" value="${id}">`).join('');if(confirm(`HAPUS SESUAI REKOMENDASI?\n\nKEEP ${keeps.length} video\nDELETE ${deletes.length} duplicate video?`))form.submit()};updateSelection();</script>
<script>document.querySelectorAll('.keep-this').forEach(button=>button.addEventListener('click',()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);const clicked=group.querySelector('.duplicate-row.recommended')?.dataset.id||group.querySelector('.duplicate-row input:checked')?.value;if(!clicked)return;group.querySelectorAll('.duplicate-row').forEach(row=>{const keep=row.dataset.id===clicked;row.dataset.keep=keep?'1':'0';row.classList.toggle('recommended',keep);row.classList.toggle('to-delete',!keep);const badge=row.querySelector('.badge');if(badge){badge.className=`badge ${keep?'keep':'delete'}`;badge.textContent=keep?'RECOMMENDED TO KEEP':'DUPLICATE'}});button.textContent=`KEEP ID ${clicked}`})});</script>
